from starlette.status import HTTP_401_UNAUTHORIZED, HTTP_403_FORBIDDEN
from typing_extensions import Annotated


class APIKeyBase(SecurityBase):
    not_authenticated_status_code: int = HTTP_401_UNAUTHORIZED

    def format_www_authenticate_header_value(self) -> str:
        return f'ApiKey in="{self.model.in_.value}", name="{self.model.name}"'

    def check_api_key(self, api_key: Optional[str], auto_error: bool) -> Optional[str]:
        if not api_key:
            if auto_error:
                headers = None
                if self.not_authenticated_status_code == HTTP_401_UNAUTHORIZED:
                    headers = {
                        "WWW-Authenticate": self.format_www_authenticate_header_value()
                    }
                raise HTTPException(
                    status_code=self.not_authenticated_status_code,
                    detail="Not authenticated",
                    headers=headers,
                )
            return None
        return api_key

